-- 0107: the foam price spreadsheet ("Price list EFF 4-20-26" and "Distributor Pricing 10-05-2026") comes in as an
-- import list. Each sheet row is matched to a customer here where the name clearly matches; the rest are matched by
-- hand on Customer prices > Import foam price sheet, where Import sets their prices. Nothing changes any price
-- until someone clicks Import there.
--  * AMBI-TITE 204 HFO ($/lb) -> AMB-TITE-20 and AMB-TITE-20-W. AMBI-SEAL 5.0 -> AMB-SEAL-50 and AMB-SEAL-50-W.
--    AMBI-JACK -> AMB-JACK. AMBI-ROOF -> AMB-ROOF-28. The old W&SW column and the old 1,000 lb block (Q-Z) are left out.
--  * A customer's notes go on their price page. Distributor prices (the newer sheet) win over the first sheet.
-- Run AFTER 0106. Safe to run again (rows already there are left as they are).

do $ext$
begin
  begin
    create extension if not exists pg_trgm with schema extensions;
  exception when others then
    create extension if not exists pg_trgm;
  end;
end $ext$;

create table if not exists public.price_import_rows (
  id               bigint generated always as identity primary key,
  source           text not null,
  raw_name         text not null,
  name             text not null,
  state            text,
  rep              text,
  hfo              numeric(12,4),
  seal             numeric(12,4),
  jack             numeric(12,4),
  roof             numeric(12,4),
  eff_on           date,
  notes            text,
  company_id       uuid references public.companies(id) on delete set null,
  matched_by       text,
  skip             boolean not null default false,
  imported_at      timestamptz,
  imported_by_name text,
  unique (source, raw_name)
);
alter table public.price_import_rows enable row level security;
drop policy if exists price_import_rows_read on public.price_import_rows;
create policy price_import_rows_read on public.price_import_rows for select to authenticated using (public.can_price());

-- A name boiled down for matching: "3D Spray Foam & Coatings, LLC" -> "3dsprayfoamcoatings".
create or replace function public.price_norm(t text) returns text
language sql immutable as $fn$
  select regexp_replace(
           regexp_replace(
             regexp_replace(regexp_replace(lower(coalesce(t, '')), '\*\*[^*]*\*\*|\([^)]*\)', ' ', 'g'), '&', ' and ', 'g'),
             '\m(l\.?l\.?c|inc|incorporated|co|corp|corporation|company|ltd|the|dba|and)\M\.?', ' ', 'g'),
         '[^a-z0-9]+', '', 'g')
$fn$;

-- Match rows that have no customer yet: the same name, else one name starting with the other, else a name that's
-- nearly the same (same state where both have one). Only when exactly one customer fits.
create or replace function public.price_import_automatch() returns int
language plpgsql security definer set search_path = public, extensions as $fn$
declare r record; hit uuid[]; n int := 0; how text; k text;
begin
  for r in select * from public.price_import_rows where company_id is null and not skip and imported_at is null loop
    k := public.price_norm(r.name);
    continue when length(k) < 4;
    how := 'same name';
    hit := array(select c.id from public.companies c
                  where c.active and (public.price_norm(c.name) = k or public.price_norm(c.qb_name) = k));
    if cardinality(hit) > 1 then
      hit := array(select c.id from public.companies c where c.id = any(hit) and c.state = r.state);
    end if;
    if cardinality(hit) <> 1 then
      how := 'name starts the same';
      hit := array(select c.id from public.companies c
                    where c.active and least(length(public.price_norm(c.name)), length(k)) >= 10
                      and (public.price_norm(c.name) like k || '%' or k like public.price_norm(c.name) || '%')
                      and (coalesce(r.state, '') = '' or coalesce(c.state, '') = '' or c.state = r.state));
    end if;
    if cardinality(hit) <> 1 then
      how := 'nearly the same name';
      hit := array(select c.id from public.companies c
                    where c.active and left(public.price_norm(c.name), 5) = left(k, 5)
                      and similarity(public.price_norm(c.name), k) >= 0.75
                      and (coalesce(r.state, '') = '' or coalesce(c.state, '') = '' or c.state = r.state));
    end if;
    if cardinality(hit) = 1 then
      update public.price_import_rows set company_id = hit[1], matched_by = how where id = r.id;
      n := n + 1;
    end if;
  end loop;
  return n;
end $fn$;
revoke all on function public.price_import_automatch() from public, anon, authenticated;

-- Staff match a row by hand (company null clears it), or skip it.
create or replace function public.price_import_set(p_row bigint, p_company uuid, p_skip boolean default false) returns void
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.can_price() then raise exception 'Only admins and price approvers change prices.'; end if;
  update public.price_import_rows
     set company_id = case when p_skip then company_id else p_company end,
         matched_by = case when p_skip then matched_by when p_company is null then null else 'by hand' end,
         skip = coalesce(p_skip, false)
   where id = p_row and imported_at is null;
end $fn$;
revoke all on function public.price_import_set(bigint, uuid, boolean) from public, anon;
grant execute on function public.price_import_set(bigint, uuid, boolean) to authenticated;

-- Import every matched row (or just p_rows): the foam prices go on the customer and its locations, and the notes on
-- their price page. Rows from the distributor sheet go last, so they win.
create or replace function public.price_import_run(p_rows bigint[] default null) returns jsonb
language plpgsql security definer set search_path = public as $fn$
declare
  r record; c uuid; m record; who text := coalesce(public.my_name(), 'AMBIT'); n_rows int := 0; n_prices int := 0;
begin
  if not public.can_price() then raise exception 'Only admins and price approvers change prices.'; end if;
  for r in
    select * from public.price_import_rows
     where company_id is not null and not skip and imported_at is null and (p_rows is null or id = any(p_rows))
     order by (source like 'Distributor%'), id
  loop
    for c in select r.company_id union select k.id from public.companies k where k.credit_parent_id = r.company_id and k.active loop
      for m in
        select p.id, v.price from (values ('AMB-TITE-20', r.hfo), ('AMB-TITE-20-W', r.hfo), ('AMB-SEAL-50', r.seal), ('AMB-SEAL-50-W', r.seal),
                                          ('AMB-JACK', r.jack), ('AMB-ROOF-28', r.roof)) as v(sku, price)
          join public.products p on upper(p.sku) = v.sku
         where v.price is not null
      loop
        perform public.price_write(c, m.id, m.price, 'lb', 'import', left(r.source, 60), least(coalesce(r.eff_on, (now() at time zone 'America/Chicago')::date), (now() at time zone 'America/Chicago')::date), who);
        n_prices := n_prices + 1;
      end loop;
      if coalesce(trim(r.notes), '') <> '' then
        update public.companies set price_note = case when coalesce(price_note, '') = '' then trim(r.notes)
                                                      when position(trim(r.notes) in price_note) > 0 then price_note
                                                      else price_note || E'\n' || trim(r.notes) end
         where id = c;
      end if;
    end loop;
    update public.price_import_rows set imported_at = now(), imported_by_name = who where id = r.id;
    n_rows := n_rows + 1;
  end loop;
  return jsonb_build_object('rows', n_rows, 'prices', n_prices);
end $fn$;
revoke all on function public.price_import_run(bigint[]) from public, anon;
grant execute on function public.price_import_run(bigint[]) to authenticated;

-- The two sheets.
on conflict (source, raw_name) do nothing;

select public.price_import_automatch();

-- Check: rows matched to a customer, and rows still to match by hand.
select count(*) filter (where company_id is not null and not skip) as "Matched",
       count(*) filter (where company_id is null and not skip) as "To match by hand",
       count(*) filter (where skip) as "No prices (skipped)"
  from public.price_import_rows;
